class StationElement extends HTMLElement {
  set presenter(p) { this.#presenter = p; }        // host injects
  query() { return this.querySelector('input').value; }
  showTotal(total) {
    this.querySelector('output').textContent = total.toFixed(2);
  }
  connectedCallback() { this.addEventListener('change',
      () => this.#presenter.queryChanged(this.query())); }
}
customElements.define('station-view', StationElement);

